private void PageHeader_BeforePrint(object sender, System.Drawing.Printing.PrintEventArgs e) {


}

private void xrTableCell1_BeforePrint(object sender, System.Drawing.Printing.PrintEventArgs e) {
var parametraRaporti = AlphaWebReports.raporteUtil.DeserializoParametraPerKonstruktorRaporti(this.Extensions["parametraRaporti"]);

            if (GetCurrentColumnValue("KODI") != null)
            {
                    xrTableCell1.NavigateUrl = "javascript:window.myFaqeCelje.hapFaqeNeTabTeRi('RaportiShpejte.aspx?scopeID="+parametraRaporti.ScopeID+"&guidString=" + parametraRaporti.GuidString+ "&idraporti=" + parametraRaporti.IdSubRaporti+ "&filterKartela=" + GetCurrentColumnValue("KODI") + "&printo=0&Sesioni=true')";
                    xrTableCell1.Target = "_self";

            }

}

int row = 0;
private void GroupHeader1_BeforePrint(object sender, System.Drawing.Printing.PrintEventArgs e) {
            if (row % 2 == 0)
                GroupHeader1.Styles.Style = (DevExpress.XtraReports.UI.XRControlStyle)StyleSheet["PermbajtjaRaportEven"];
            else
                GroupHeader1.Styles.Style = (DevExpress.XtraReports.UI.XRControlStyle)StyleSheet["PermbajtjaRaportOdd"];
            row++; 
}

private void Rap_Artikujteshitur_BeforePrint(object sender, System.Drawing.Printing.PrintEventArgs e) {
	var parametraRaporti = AlphaWebReports.raporteUtil.DeserializoParametraPerKonstruktorRaporti(this.Extensions["parametraRaporti"]);

      var parameters = AlphaWebReports.raporteUtil.DeserializoParametrat(this.Extensions["filtrat"]);
      var formati = parameters.Find(param => param.Emri == "filterFormatNumri");
	shifraPasPresjes = (formati != null) ? formati.Vlera : "2";	
	AlphaWebReports.raporteUtil.vendosFormatinEFushesSeRaportit("{0:N"+shifraPasPresjes+"}",0.ToString("N" + shifraPasPresjes), true,xrTableCell3,xrTableCell10, xrTableCell11, xrTableCell12,xrTableCell13, xrTableCell14, xrTableCell15, xrTableCell16,xrTableCell17, xrTableCell19,xrTableCell20, xrTableCell21, xrTableCell22, xrTableCell11);
xrPictureBox1.Image = AlphaWebReports.raporteUtil.MerrLogoNdermarrje(this.Extensions["ndermarrjeLogo"]);
}

private void filtraTable_BeforePrint(object sender, System.Drawing.Printing.PrintEventArgs e) {
	AlphaWebReports.raporteUtil.shtoFiltra((XRTable)sender, null, AlphaWebReports.raporteUtil.DeserializoParametrat(this.Extensions["filtrat"]));
}

private void xrTableCell11_SummaryReset(object sender, System.EventArgs e) {
	vleratot = 0.0; 
	sasiatot = 0.0; 
}

private void xrTableCell11_SummaryRowChanged(object sender, System.EventArgs e) {
	vleratot = vleratot + Convert.ToDouble(GetCurrentColumnValue("VleftaRreshtit"));
	sasiatot = sasiatot + Convert.ToDouble(GetCurrentColumnValue("SASIA"));
}

private void xrTableCell11_SummaryGetResult(object sender, DevExpress.XtraReports.UI.SummaryGetResultEventArgs e) {
	e.Result = sasiatot != 0 ? (vleratot / sasiatot) :  vleratot;
	e.Handled = true; 
}
